// src/js/Chat/Gif/TenorApi.js
import axios from "axios";

const TENOR_KEY = process.env.REACT_APP_TENOR_KEY;
const BASE = "https://g.tenor.com/v1";

export async function searchGifs(query, { limit = 24, pos = null } = {}) {
  if (!TENOR_KEY) {
    throw new Error("Tenor API key not configured. Set REACT_APP_TENOR_KEY in .env");
  }
  const params = {
    key: TENOR_KEY,
    q: query || "trending",
    limit,
    media_filter: "minimal", // menor payload
    // locale: "pt_BR"
  };
  if (pos) params.pos = pos;

  const url = `${BASE}/search`;
  const res = await axios.get(url, { params });
  // returns tenor result + next pos
  return {
    results: res.data && res.data.results ? res.data.results : [],
    next: res.data && res.data.next ? res.data.next : null
  };
}

export async function trendingGifs({ limit = 24, pos = null } = {}) {
  if (!TENOR_KEY) {
    throw new Error("Tenor API key not configured. Set REACT_APP_TENOR_KEY in .env");
  }
  const params = {
    key: TENOR_KEY,
    limit,
    media_filter: "minimal"
  };
  if (pos) params.pos = pos;

  const url = `${BASE}/trending`;
  const res = await axios.get(url, { params });
  return {
    results: res.data && res.data.results ? res.data.results : [],
    next: res.data && res.data.next ? res.data.next : null
  };
}
